def selected(key):
 group='bench' if key=='workshop' else key
 rows=[o for o in metadata['objects'] if o['group']==group]
 if key=='pump':rows=[o for o in rows if o['bounds'][1][0]<-9.5]
 if key=='workshop':rows=[o for o in rows if o['id'].startswith(('Red workshop bench','Workshop bench metal top','Bench drawer handle'))]
 if key=='wreck':rows=[o for o in rows if o['id'].startswith('Wreck 0 ')]
 assert rows,key
 return rows
