for key,kind,role,count,poly,attachment,front,prompt,reject in asset_specs:
 rows=selected(key);lo=[min(o['bounds'][0][i] for o in rows) for i in range(3)];hi=[max(o['bounds'][1][i] for o in rows) for i in range(3)]
 assets.append({'id':key,'class':kind,'function':role,'description':prompt,'dimensionsMeters':[hi[i]-lo[i] for i in range(3)],'intendedInstances':count,'attachmentFace':attachment,'semanticFront':front,'targetPolycount':poly,'referenceApproved':False,'rejectionCriteria':reject.split('; '),'image':{'prompt':prompt,'generator':'Blender 4.3.2 native reference-guided concept render','source':f'images/{key}-study.png','approved':False,'approvedBy':'','approvedAt':''}})
