for i,o in enumerate(openings):
 width=o['widthMeters'];height=o['heightMeters'];w=300;h=210
 mask=Image.new('L',(w,h),0);md=ImageDraw.Draw(mask);scale=min(240/width,160/height);rw=round(width*scale);rh=round(height*scale);x=(w-rw)//2;y=(h-rh)//2;md.rectangle((x,y,x+rw,y+rh),fill=255)
 path=f"masks/{o['id']}.png";mask.save(ROOT/path);cutter=f"masks/{o['id']}-cutter.json"
