 o.update(mask=path,cutter=cutter,approvedBy='',approvedAt='')
 cx=(i%3)*300;cy=(i//3)*250;contact.paste(mask.convert('RGB'),(cx,cy));draw.text((cx+12,cy+218),f"{o['id']}  {width:.2f} x {height:.2f} m",fill='black')
